import unittest

from gol import (
    Grid,
    blinker,
    glider,
    neighbors,
    next_generation,
    parse,
    render,
)


class TestNeighbors(unittest.TestCase):
    def test_returns_eight_cells(self):
        result = set(neighbors((2, 3)))
        expected = {
            (1, 2), (1, 3), (1, 4),
            (2, 2),         (2, 4),
            (3, 2), (3, 3), (3, 4),
        }
        self.assertEqual(result, expected)


class TestBlinker(unittest.TestCase):
    def test_period_two(self):
        g = blinker()
        g2 = next_generation(g)
        g3 = next_generation(g2)
        # Horizontal line rotates to vertical and back.
        self.assertEqual(g2, parse(\"\"\"
        .#.
        .#.
        .#.
        \"\"\"))
        self.assertEqual(g, g3)


class TestGlider(unittest.TestCase):
    def test_moves_diagonally_and_keeps_shape(self):
        g = glider()
        for _ in range(4):
            g = next_generation(g)
        g2 = glider()
        for _ in range(4):
            g2 = next_generation(g2)
        self.assertEqual(g, g2)


class TestParseRender(unittest.TestCase):
    def test_roundtrip(self):
        text = \".#.\\n..#\\n###\\n\"
        grid = parse(text)
        self.assertEqual(render(grid), text)


class TestGrid(unittest.TestCase):
    def test_isolated_cell_dies(self):
        g: Grid = {(0, 0)}
        self.assertEqual(next_generation(g), set())

    def test_block_is_still_life(self):
        block = parse(\"##\\n##\")
        self.assertEqual(next_generation(block), block)


if __name__ == \"__main__\":
    unittest.main()
